mapper.select:
SELECT a.STATUS as status, a.COUNTER_ID as counterId, a.COUNTER_NAME as counterName, a.COUNTER_TYPE1 as counterType1, a.COUNTER_TYPE2 as counterType2, a.CREATE_USER as createUser, a.CREATE_TIME as createTime, a.UPDATE_USER as updateUser, a.UPDATE_TIME as updateTime, a.SVR_DATA_SOURCES as dataSource, '' as uuid FROM chb_mst_counter_party a
not EXISTS ( SELECT 1 from CHB_MST_COUNTER_PARTY_ERRORDATA c where c.COUNTER_ID=a.COUNTER_ID and c.STATUS in('A','E') )
#{counterId,jdbcType=VARCHAR}
#{counterType2,jdbcType=VARCHAR}
#{status,jdbcType=VARCHAR}
union all SELECT 'A' as status, c.COUNTER_ID as counterId, c.COUNTER_NAME as counterName, c.COUNTER_TYPE1 as counterType1, c.COUNTER_TYPE2 as counterType2 , c.CREATE_USER as createUser, c.CREATE_TIME as createTime, c.UPDATE_USER as updateUser, c.UPDATE_TIME as updateTime, 'DB' as dataSource, c.DATAUUID as uuid FROM chb_mst_counter_party_errordata c
c.STATUS in('A','E')
#{counterId,jdbcType=VARCHAR}
#{counterType2,jdbcType=VARCHAR}
and 1 = 2

mapper.update:
update chb_mst_counter_party set
STATUS= #{status,jdbcType=VARCHAR},SVR_DATA_SOURCES= #{dataSource,jdbcType=VARCHAR},
COUNTER_NAME= #{counterName,jdbcType=VARCHAR},COUNTER_TYPE1= #{counterType1,jdbcType=VARCHAR},COUNTER_TYPE2= #{counterType2,jdbcType=VARCHAR},
UPDATE_USER= #{updateUser,jdbcType=VARCHAR},UPDATE_TIME= #{updateTime,jdbcType=DATE}
where
	COUNTER_ID = #{counterId,jdbcType=VARCHAR}

mapper.delete:
delete from chb_mst_counter_party_errordata a
where
COUNTER_ID = #{counterId,jdbcType=VARCHAR}

mapper.select:
SELECT count(1) from ( SELECT 1 from CHB_MST_COUNTER_PARTY a where a.STATUS in('A','E') and not EXISTS ( SELECT 1 from chb_mst_counter_party_errordata b WHERE b.COUNTER_ID=a.COUNTER_ID and b.STATUS in('A','E') ) and
a.COUNTER_ID = #{item.counterId,jdbcType=VARCHAR}
union all SELECT 1 from chb_mst_counter_party_errordata c where c.STATUS in('A','E') and
c.COUNTER_ID = #{item.counterId,jdbcType=VARCHAR}
)tmp

